let imagePending=0,imageTask=0;
let data={users:[],books:[],requests:[]},storageError='',current=null,search='',genre='전체',condition='',imageDraft='',busy=false;const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),user=()=>data.users.find(u=>u.id===current),book=id=>data.books.find(b=>b.id===id),person=id=>data.users.find(u=>u.id===id),go=p=>location.hash=p;
async function mutate(fn){const backup=structuredClone(data);try{fn();data=await cloud.sync(backup,data);clearMedia();}catch(e){data=backup;throw e;}}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3200);}function avatar(u){return u?.avatar?`<img class="avatar" src="${esc(u.avatar)}" alt="프로필">`:`<span class="avatar" ${u?.id&&!u.avatar?`data-profile-avatar="${esc(u.id)}"`:""}>${esc(u?.nickname?.[0]||'책')}</span>`;}function cover(b){return `<div ${b.id&&b.cover===undefined?`data-book-cover="${esc(b.id)}"`:""} class="cover ${b.cover?.startsWith('data:image/')?'photo':esc(b.cover||'light')}">${b.cover?.startsWith('data:image/')?`<img src="${esc(b.cover)}" alt="${esc(b.title)} 표지">`:`<strong>${esc(b.title)}</strong><em>${({essay:'⌁',store:'▤',fish:'◒',light:'✳',sapiens:'人',winter:'❋',sea:'≈',art:'▥'})[b.cover]||'❧'}</em><small>${esc(b.author)} · BOOKIT LIBRARY</small>`}</div>`;}
function listingLabel(status){return {available:'교환 가능',reserved:'교환 진행 중',completed:'교환 완료',archived:'등록 종료'}[status]||'상태 확인 중';}
function listingActions(b){
 const history=data.requests.some(r=>[r.target,r.offered].includes(b.id));
 if(b.status==='available')return `<a href="#/edit/${esc(b.id)}">수정</a><button class="quiet" data-listing="archived" data-book="${esc(b.id)}">등록 종료</button>${!history?`<button class="quiet danger" data-delete="${esc(b.id)}">삭제</button>`:''}`;
 if(b.status==='archived')return `<button class="quiet" data-listing="available" data-book="${esc(b.id)}">다시 등록</button>`;
 return `<span class="hint">${listingLabel(b.status)}</span>`;
}
function icon(name){const paths={book:'<path d="M4 4.5h6a3 3 0 0 1 3 3V21a4 4 0 0 0-4-2H4z"/><path d="M20 4.5h-4a3 3 0 0 0-3 3V21a4 4 0 0 1 4-2h3z"/>',home:'<path d="m3 10 9-7 9 7v10H5V10"/><path d="M9 20v-7h6v7"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',exchange:'<path d="M4 7h15l-4-4M20 17H5l4 4M20 7l-4 4M4 17l4-4"/>',person:'<circle cx="12" cy="7.5" r="4"/><path d="M4.5 21v-2a7.5 7.5 0 0 1 15 0v2"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',plus:'<path d="M12 4v16M4 12h16"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 7a7 7 0 0 1 12-1l2 3M18 17a7 7 0 0 1-12 1l-2-3"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',filter:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="2" fill="currentColor"/><circle cx="15" cy="17" r="2" fill="currentColor"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${paths[name]||paths.book}</svg>`;}
function timeAgo(value){const date=Number(value);if(!Number.isFinite(date)||date<=0)return '';const minutes=Math.max(0,Math.floor((Date.now()-date)/60000));return minutes<1?'방금 전':minutes<60?`${minutes}분 전`:minutes<1440?`${Math.floor(minutes/60)}시간 전`:minutes<10080?`${Math.floor(minutes/1440)}일 전`:new Date(date).toLocaleDateString('ko-KR',{month:'numeric',day:'numeric',timeZone:'Asia/Seoul'});}
function requestBadge(status){return {'대기 중':'status-wait','수락됨':'status-ok','교환 완료':'status-done','거절됨':'status-no','취소됨':'status-no'}[status]||'';}
function navigation(path,mobile=false){
 const section=['received','sent','exchange','history'].includes(path)?'received':['home','search','book'].includes(path)?'home':path;
 const pending=current?data.requests.filter(r=>(r.to===current&&r.status==='대기 중')||(r.status==='수락됨'&&[r.from,r.to].includes(current)&&r.cancellations?.length&&!r.cancellations.includes(current))).length:0;
 const items=[['home','홈','home','#/'],['recommend','추천','spark','#/recommend'],['received','교환','exchange','#/received'],['profile',mobile?'나의 책잇':user()?.nickname||'로그인','person',user()?'#/profile':'#/login']];
 return `<nav class="${mobile?'bottom-nav':'top-nav'}" aria-label="${mobile?'모바일 메뉴':'주 메뉴'}">${items.map(([key,label,symbol,href])=>`<a href="${href}" class="${section===key?'active':''}" ${section===key?'aria-current="page"':''}><span class="nav-icon">${icon(symbol)}${key==='received'&&pending?`<span class="nav-count" aria-label="확인할 교환 ${pending}건">${pending>9?'9+':pending}</span>`:''}</span><span class="nav-label">${esc(label)}</span></a>`).join('')}</nav>`;
}
function card(b){const mine=b.owner===current;return `<article class="card"><a href="#/book/${esc(b.id)}" class="cardimg" aria-label="${esc(b.title)} 상세 보기">${cover(b)}</a><div class="cardbody"><a class="card-title" href="#/book/${esc(b.id)}"><h3>${esc(b.title)}</h3></a><div class="author">${esc(b.author||'저자 미상')}<span class="meta-dot">·</span>${timeAgo(b.created)}</div><div class="listing-line"><strong class="book-state state-${esc(b.status)}">${listingLabel(b.status)}</strong><div class="badges"><span class="badge neutral">${esc(b.genre)}${b.genreDetail?` · ${esc(b.genreDetail)}`:''}</span><span class="badge">${esc(b.condition)}</span></div></div>${b.conditionDetail?`<p class="hint condition-summary">${esc(b.conditionDetail.slice(0,75))}${b.conditionDetail.length>75?'…':''}</p>`:''}<div class="owner"><span class="owner-name">${avatar(person(b.owner))}${esc(person(b.owner)?.nickname)}</span><span class="book-actions">${mine?listingActions(b):`<a class="view-book" href="#/book/${esc(b.id)}">책 보기 ${icon('arrow')}</a>`}</span></div></div>${b.reason?`<div class="reason">${icon('spark')}<span>${esc(b.reason)}</span></div>`:''}</article>`;}

const empty=s=>`<div class="empty">📖<p>${s}</p></div>`,option=(arr,value)=>arr.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('');
const BOOKS_PER_PAGE=12,listPages={home:1,search:1,recommend:1};
let lastListRoute='/';
function paginateBooks(items,key){
 const pages=Math.max(1,Math.ceil(items.length/BOOKS_PER_PAGE));
 const page=Math.min(pages,Math.max(1,listPages[key]||1));
 listPages[key]=page;
 const offset=(page-1)*BOOKS_PER_PAGE;
 return {items:items.slice(offset,offset+BOOKS_PER_PAGE),page,pages,total:items.length,start:offset+1,end:Math.min(offset+BOOKS_PER_PAGE,items.length)};
}
function pagination(list){
 if(list.pages<2)return '';
 const start=Math.max(1,Math.min(list.page-1,list.pages-2));
 const numbers=Array.from({length:Math.min(3,list.pages)},(_,i)=>start+i);
 return `<div class="list-pagination"><p class="page-summary" role="status">전체 ${list.total}권 중 ${list.start===list.end?list.end:`${list.start}–${list.end}`}권 · ${list.page} / ${list.pages} 페이지</p><nav class="page-controls" aria-label="책 목록 페이지"><button type="button" data-page="${list.page-1}" ${list.page===1?'disabled':''} aria-label="이전 페이지">이전</button>${numbers.map(n=>`<button type="button" data-page="${n}" aria-label="${n}페이지" ${n===list.page?'aria-current="page"':''}>${n}</button>`).join('')}<button type="button" data-page="${list.page+1}" ${list.page===list.pages?'disabled':''} aria-label="다음 페이지">다음</button></nav></div>`;
}
function home(rec=false){const key=rec?'recommend':location.hash==='#/search'?'search':'home';lastListRoute=key==='home'?'/':'/'+key;const u=user();let all=data.books.filter(b=>b.status==='available'&&(!search||(b.title+b.author+(b.genreDetail||'')).toLowerCase().includes(search.toLowerCase()))&&(genre==='전체'||b.genre===genre)&&(!condition||b.condition===condition)).sort((a,b)=>b.created-a.created);if(rec&&u)all=recommend(data,u);const page=paginateBooks(all,key);return `${!search&&!rec?`<section class="market-intro"><div><span class="eyebrow">책으로 이어지는 이웃</span><h1>우리들의 책장</h1><p>당신의 책장에 잠든 이야기, 누군가의 다음 페이지로.<br>다 읽은 책은 나누고, 새로운 취향을 발견해요.</p></div><div class="community-summary"><span>${icon('book')} 함께 나누는 책 <b>${data.books.length}</b></span><span>책으로 연결된 이웃 <b>${data.users.length}</b></span></div></section>`:''}<div class="sectionhead ${!search&&!rec?'home-sectionhead':''}"><div><h2 id="book-results-heading" tabindex="-1">${rec?'나를 위한 추천 책':search?`“${esc(search)}” 검색 결과`:'새로운 주인을 기다리는 책'}</h2><p>${rec?'내 책과 관심 장르에 맞는 다음 이야기를 만나보세요.':'이웃의 책장에서, 나의 다음 이야기를 찾아보세요.'}</p></div><span class="textlink">${all.length}권</span></div>${rec?`<div class="notice recommendation-note">${icon('spark')}<span>장르·키워드·교환 조건을 활용한 맞춤 추천입니다. ${u?'<a href="#/profile">관심사 수정</a>':'<a href="#/login">로그인하고 추천 받기</a>'}</span></div>`:`<div class="chips" aria-label="분야 필터">${['전체',...genres].map(g=>`<button data-genre="${g}" aria-pressed="${genre===g}" class="chip ${genre===g?'active':''}">${g}</button>`).join('')}</div><div class="filters"><div class="condition-filter">${icon('filter')}<select id="condition" aria-label="책 상태"><option value="">모든 책 상태</option>${option(conditions,condition)}</select></div><span class="hint">최신 등록순</span></div>`}<div class="grid">${catalogLoading?empty('책 목록을 불러오고 있어요…'):catalogFailed?empty('책 목록에 연결하지 못했어요. 위의 새로고침을 눌러주세요.'):rec&&!u?empty(initialLoading?'로그인 정보를 확인 중이에요…':'로그인하면 내 취향에 맞는 책을 추천해드려요.'):page.items.map(card).join('')||empty('조건에 맞는 책이 없어요. 다른 검색어나 필터를 사용해보세요.')}</div>${!catalogLoading&&!catalogFailed&&(!rec||u)?pagination(page):''}${!rec?`<a class="discovery-link" href="#/recommend"><span class="discovery-icon">${icon('spark')}</span><span><b>다음에 읽을 책, 고민된다면?</b><small>내 책과 관심 장르에 꼭 맞는 새로운 이야기를 만나보세요.</small></span>${icon('arrow')}</a>`:''}`;}

function auth(signup){return `<form class="form panel" id="auth"><span class="eyebrow">WELCOME TO BOOKIT</span><h1>${signup?'함께 나눌 이야기를 시작해요':'다시 만나 반가워요'}</h1><p class="hint">책과 사람 사이, 새로운 이야기가 이어지는 곳.</p>${signup?'<label for="nickname">닉네임</label><input id="nickname" name="nickname" required maxlength="20">':''}<label for="email">이메일</label><input id="email" name="email" type="email" required><label for="password">비밀번호</label><input id="password" name="password" type="password" minlength="8" required autocomplete="${signup?'new-password':'current-password'}"><small>8자 이상 입력해주세요.</small><div class="error" id="formerror"></div><button class="primary">${signup?'회원가입':'로그인'}</button><p class="hint">${signup?'이미 계정이 있나요? <a href="#/login">로그인</a>':'처음 오셨나요? <a href="#/signup">회원가입</a> · <a href="#/forgot-password">비밀번호 찾기</a>'}</p><div class="notice">이메일·비밀번호는 Supabase 인증으로 안전하게 처리합니다. 기존 데모 계정과 별도로 가입해주세요. 가입 메일의 6자리 확인 코드는 <a href="#/verify">여기에서 입력</a>할 수 있어요.</div></form>`;}
function editor(id){if(!user())return auth(false);const b=id?book(id):null;if(id&&(!b||b.owner!==current))return empty('수정 권한이 없어요.');if(b?.status==='archived')return `<div class="notice"><p>등록을 종료한 책이에요. 다시 등록한 뒤 내용을 수정할 수 있어요.</p><button class="secondary" data-listing="available" data-book="${esc(b.id)}">다시 등록하고 수정</button></div>`;if(b&&b.cover===undefined){loadMedia('book',b.id).then(value=>{b.cover=value||'light';if(location.hash==='#/edit/'+id)render();}).catch(()=>{const box=$('#editorimage');if(box)box.textContent='기존 표지를 불러오지 못했어요. 원본 보존을 위해 편집을 기다리고 있어요. 목록 새로고침으로 다시 시도해주세요.';});return '<div class="empty" id="editorimage" role="status">기존 표지를 불러오고 있어요…</div>';}imageDraft=b?.cover||'light';return `<form id="bookform" class="form panel" data-id="${id||''}"><span class="eyebrow">SHARE YOUR STORY</span><h1>${b?'등록한 책 수정':'다음 독자를 기다리는 책'}</h1><p class="hint">책 한 권에 담긴 이야기를 이웃과 나눠보세요.</p><div class="notice draft-notice"><span data-draft-status>작성 내용은 이 계정으로 이 탭에 임시 저장돼요.</span><button type="button" class="quiet" id="discard-book-draft">임시 내용 비우기</button></div><label>책 표지</label><div id="preview">${cover(b||{title:'나의 책',author:'',cover:'light'})}</div><input id="image" type="file" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG, WebP · 최대 2MB · 업로드 시 자동 압축</small><div class="actions"><button type="button" class="secondary" id="removeimage">사진 삭제</button></div><label for="title">책 제목 *</label><input id="title" name="title" required maxlength="120" value="${esc(b?.title)}"><label for="author">저자</label><input id="author" name="author" maxlength="80" value="${esc(b?.author)}"><fieldset class="book-fields"><legend>분야 / 장르</legend><label for="bookgenre">기본 분야</label><select id="bookgenre" name="genre">${option(genres,b?.genre)}</select><label for="genreDetail">세부 장르 · 직접 입력</label><input id="genreDetail" name="genreDetail" ${b?.genre==='기타'?'required':''} maxlength="40" list="genreExamples" value="${esc(b?.genreDetail)}" placeholder="예: 추리·미스터리, 경제·경영, 요리" aria-describedby="genre-detail-help"><datalist id="genreExamples">${(genreExamples[b?.genre||genres[0]]||[]).map(value=>`<option value="${esc(value)}"></option>`).join('')}</datalist><small id="genre-detail-help">예시에서 고르거나 원하는 분류를 40자 이내로 직접 적어주세요. 기본 분야는 기존 검색·추천에 사용돼요.</small></fieldset><fieldset class="book-fields"><legend>책 상태</legend><label for="bookcondition">기본 상태</label><select id="bookcondition" name="condition" aria-describedby="condition-guide">${option(conditions,b?.condition)}</select><small id="condition-guide">${conditionGuides[b?.condition||'새 책']}</small><label for="conditionDetail">상세 상태 · 직접 입력</label><textarea id="conditionDetail" name="conditionDetail" ${b?.condition==='기타'?'required':''} maxlength="300" rows="3" placeholder="예: 밑줄·필기 없어요. 표지 오른쪽 모서리에 작은 접힘이 있어요." aria-describedby="condition-detail-help">${esc(b?.conditionDetail)}</textarea><small id="condition-detail-help">밑줄·필기, 표지·책등 손상, 접힘, 변색, 부록 유무 등을 300자 이내로 알려주세요. 책의 상태를 자유롭게 작성하고 수정할 수 있어요.</small><button type="button" class="quiet" id="clear-condition-detail">설명 비우기</button></fieldset><label>책 소개 / 교환 메모</label><textarea name="description" maxlength="1500">${esc(b?.description)}</textarea><label>원하는 교환 조건</label><input name="terms" maxlength="300" value="${esc(b?.terms)}" placeholder="예: 소설이나 에세이와 교환하고 싶어요"><div class="two"><div><label>연락 수단</label><select name="method">${option(['이메일','전화번호','기타'],b?.method||user().method)}</select></div><div><label>연락처 *</label><input name="contact" required maxlength="100" value="${esc(b?.contact||user().contact)}"></div></div><div class="notice">🔒 연락처는 교환 수락 후 상대방에게만 표시돼요.</div><div id="formerror" class="error"></div><button class="primary" ${b?.status!=='available'&&b?'disabled':''}>${b?'수정 저장':'책 등록하기'}</button>${b&&b.status!=='available'?'<p class="hint">진행 중이거나 완료된 책은 수정할 수 없어요.</p>':''}</form>`;}
function detail(id){const b=book(id);if(!b)return empty('책을 찾을 수 없어요.');const own=b.owner===current,u=person(b.owner);return `<a class="hint" href="#${lastListRoute}">← 책 목록으로</a><div class="detail"><div class="detailart">${cover(b)}</div><section><div class="badges"><span class="badge">${esc(b.condition)}</span><span class="badge neutral">${esc(b.genre)}${b.genreDetail?` · ${esc(b.genreDetail)}`:''}</span><span class="badge orange">${listingLabel(b.status)}</span></div><h1>${esc(b.title)}</h1><p class="author">${esc(b.author)}</p><p>${esc(b.description)||'등록된 소개가 없어요.'}</p>${b.conditionDetail?`<section class="notice"><h3>책 상태 자세히 보기</h3><p class="book-detail-note">${esc(b.conditionDetail)}</p></section>`:''}<div class="panel">${avatar(u)}<strong>${esc(u.nickname)}</strong><p class="hint">${esc(u.bio)}</p><hr style="border:0;border-top:1px solid var(--line)"><h4>원하는 교환 조건</h4><p>${esc(b.terms)||'좋은 책이라면 모두 좋아요.'}</p></div>${own?`<div class="actions book-actions">${listingActions(b)}</div>${b.status==='archived'?'<div class="notice">등록을 종료했어요. 검색·추천과 새 신청에서 제외되며, 기존 교환 기록은 유지돼요. 다시 등록해도 마감된 신청은 재개되지 않아요.</div>':''}`:b.status!=='available'?'<div class="notice">이 책은 현재 새로운 신청을 받지 않아요.</div>':!user()?'<div class="notice">로그인하고 내 책으로 교환을 제안해보세요.</div><a class="btn" href="#/login">로그인하고 교환 신청</a>':`<form id="proposal" class="form" data-target="${id}"><label>교환할 내 책 *</label><select name="offered" required><option value="">책을 선택해주세요</option>${data.books.filter(x=>x.owner===current&&x.status==='available').map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join('')}</select><a class="hint" href="#/new">교환할 책 등록하기 →</a><label>신청 메시지</label><textarea name="message" maxlength="1000" placeholder="책과 함께 전하고 싶은 말을 남겨주세요."></textarea><div id="formerror" class="error"></div><button class="primary">교환 신청하기 →</button><p class="hint">연락처는 신청이 수락된 뒤 공개됩니다.</p></form>`}</section></div>`;}
function tabs(active){return `<div class="tabs">${[['profile','내 책장'],['received','받은 신청'],['sent','보낸 신청'],['history','교환 완료']].map(([path,t])=>`<a class="${active===path?'active':''}" href="#/${path}">${t}</a>`).join('')}</div>`;}
function profile(){if(!user())return auth(false);const u=user();return `<h1>나의 책장</h1><div class="layout"><aside class="panel"><h2>${avatar(u)}${esc(u.nickname)}</h2><p class="hint">${esc(u.bio)}</p><div class="notice">🔒 연락처 비공개<br>수락한 교환의 상대에게만 공개됩니다.</div><button class="secondary" id="logout">로그아웃</button><details><summary style="margin-top:24px;cursor:pointer">프로필 · 관심사 수정</summary><form id="profileform" class="form"><label>프로필 사진</label><input type="file" id="avatarfile" accept="image/png,image/jpeg,image/webp"><small>최대 2MB</small><label>닉네임</label><input name="nickname" required maxlength="20" value="${esc(u.nickname)}"><label>한 줄 소개</label><input name="bio" maxlength="140" value="${esc(u.bio)}"><label>연락 수단</label><select name="method">${option(['이메일','전화번호','기타'],u.method)}</select><label>연락처</label><input name="contact" required value="${esc(u.contact)}"><label>관심 장르 (여러 개 선택)</label>${genres.map(g=>`<label><input type="checkbox" name="interests" value="${g}" ${u.interests.includes(g)?'checked':''} style="width:auto"> ${g}</label>`).join('')}<label>선호 키워드</label><input name="keywords" value="${esc(u.keywords)}"><div id="formerror" class="error"></div><button class="primary">프로필 저장</button></form></details></aside><section>${legacyImport()}${tabs('profile')}<div class="sectionhead"><h2>내가 등록한 책</h2><span class="hint">오른쪽 아래 ＋로 추가해요</span></div><div class="grid">${data.books.filter(b=>b.owner===current).map(card).join('')||empty('아직 등록한 책이 없어요.')}</div></section></div>`;}
function requests(type){if(!user())return auth(false);const rs=data.requests.filter(r=>type==='received'?r.to===current:type==='sent'?r.from===current:[r.to,r.from].includes(current)&&r.status==='교환 완료').sort((a,b)=>b.created-a.created);return `<h1>${type==='received'?'받은 교환 신청':type==='sent'?'보낸 교환 신청':'함께 나눈 이야기'}</h1>${tabs(type)}${rs.map(r=>`<article class="panel request">${cover(book(r.offered))}<main><span class="badge ${requestBadge(r.status)}">${r.status}</span>${r.status==='수락됨'&&r.cancellations?.length?'<span class="badge orange">취소 협의 중</span>':''}<h3>${esc(book(r.offered).title)} ↔ ${esc(book(r.target).title)}</h3><p class="hint">${esc(person(r.from).nickname)} → ${esc(person(r.to).nickname)} · ${new Date(r.created).toLocaleDateString('ko-KR')}</p><p>${esc(r.message)||'책 교환을 제안했어요.'}</p>${r.closedReason?`<p class="hint">${r.closedReason}</p>`:''}<div class="actions"><a class="secondary" href="#/exchange/${r.id}">교환 상세</a>${r.status==='대기 중'?(r.to===current?`<button class="primary" data-action="수락됨" data-r="${r.id}">수락</button><button class="secondary" data-action="거절됨" data-r="${r.id}">거절</button>`:`<button class="secondary" data-action="취소됨" data-r="${r.id}">신청 취소</button>`):''}</div></main></article>`).join('')||empty('아직 교환 신청이 없어요. 마음에 드는 책을 찾아보세요.')}`;}
function cancellationControls(r){
 const votes=r.cancellations||[],mine=votes.includes(current);
 return `<section class="notice cancellation"><h3>교환 취소</h3><p>${votes.length?'취소 협의 중이에요. 양쪽이 동의해야 책의 예약이 해제돼요. 협의 중에는 완료 확인을 할 수 없어요.':'약속이 무산되었나요? 양쪽이 취소에 동의하면 두 책을 다시 교환할 수 있어요.'}</p><div class="actions">${!votes.length?`<button class="secondary" data-action="합의 취소" data-r="${r.id}">교환 취소 요청</button>`:mine?`<span>상대방의 취소 동의를 기다리고 있어요.</span><button class="secondary" data-action="취소 철회" data-r="${r.id}">취소 요청 철회</button>`:`<button class="secondary danger" data-action="합의 취소" data-r="${r.id}">취소에 동의</button><button class="secondary" data-action="취소 거절" data-r="${r.id}">교환 계속하기</button>`}</div></section>`;
}
function exchange(id){const r=data.requests.find(r=>r.id===id);if(!user())return auth(false);if(!r||![r.from,r.to].includes(current))return empty('접근할 수 없는 교환입니다.');const cs=contacts(data,r,current);return `<div class="form panel"><span class="eyebrow">ONE BOOK, ANOTHER CHAPTER</span><h1>우리의 책 교환</h1><span class="badge ${requestBadge(r.status)}">${r.status}</span>${r.status==='수락됨'&&r.cancellations?.length?'<span class="badge orange">취소 협의 중</span>':''}<div class="request">${cover(book(r.offered))}<b>↔</b>${cover(book(r.target))}</div><h3>${esc(book(r.offered).title)} ↔ ${esc(book(r.target).title)}</h3><p>${esc(r.message)}</p><p class="hint">신청일 ${new Date(r.created).toLocaleString('ko-KR')}</p>${r.closedReason?`<div class="notice">${r.closedReason}</div>`:''}${cs.length?`<h3>🔓 교환 당사자 연락처</h3>${cs.map(c=>`<div class="notice"><b>${esc(c.name)}</b><br>${esc(c.method)} · ${esc(c.value)}</div>`).join('')}<p class="hint">공개된 연락 수단으로 장소와 시간을 정해주세요. 실시간 채팅은 제공하지 않아요.</p><h3>교환 메모</h3>${[r.from,r.to].map(id=>`<div class="notice"><b>${esc(person(id).nickname)}</b><p>${esc(r.notes[id])||'아직 메모가 없어요.'}</p></div>`).join('')}${r.status==='수락됨'?`<form id="notes" data-r="${id}"><label>내 약속 장소 · 시간 메모</label><textarea name="note" maxlength="1000">${esc(r.notes[current])}</textarea><button class="secondary">메모 저장</button></form><div class="notice">완료 확인 ${r.confirmations.length}/2 · 양쪽 모두 확인하면 교환이 완료돼요.</div><button class="primary" data-action="완료" data-r="${id}" ${r.confirmations.includes(current)||r.cancellations?.length?'disabled':''}>${r.cancellations?.length?'취소 요청 처리 후 완료할 수 있어요':r.confirmations.includes(current)?'상대방의 완료 확인을 기다리는 중':'책을 받았어요 · 완료 확인'}</button>${cancellationControls(r)}`:'<div class="notice">✓ 두 분의 교환이 완료되었어요. 즐거운 독서 되세요!</div>'}`:`<div class="notice">${r.status==='취소됨'?'🔒 교환이 취소되어 상대방 연락처를 다시 비공개로 전환했어요.':'🔒 연락처는 교환 수락 후에만 볼 수 있어요.'}</div>`}${r.status==='대기 중'?`<div class="actions">${r.to===current?`<button class="primary" data-action="수락됨" data-r="${id}">수락</button><button class="secondary" data-action="거절됨" data-r="${id}">거절</button>`:`<button class="secondary" data-action="취소됨" data-r="${id}">신청 취소</button>`}</div>`:''}</div>`;}
function render(){if(draftHandle&&!draftHandle.save())return;draftHandle=null;imageTask++;let [path,id]=(location.hash.slice(2)||'home').split('/');if(recoveryEntry&&!location.hash.startsWith('#/'))path='reset-password';let html;try{html=initialLoading&&!['home','search','recommend','book'].includes(path)?empty('로그인 정보를 확인 중이에요…'):path==='book'&&catalogLoading?empty('책 정보를 불러오고 있어요…'):path==='forgot-password'?forgotPassword():path==='reset-password'?resetPasswordPage():path==='verify'?verify():path==='login'?auth(false):path==='signup'?auth(true):path==='new'?editor():path==='edit'?editor(id):path==='book'?detail(id):path==='profile'?profile():['received','sent','history'].includes(path)?requests(path):path==='exchange'?exchange(id):home(path==='recommend');}catch(e){html=empty('화면을 불러오지 못했어요. 새로고침 후 다시 시도해주세요.');console.error(e);}$('#app').innerHTML=`<header class="site-header"><div class="header-inner"><a class="brand" href="#/" aria-label="책잇 홈"><span class="brand-mark">${icon('book')}</span><span>책잇</span><small>우리들의 책 교환</small></a><form class="navsearch" id="search"><input aria-label="책 제목 또는 저자 검색" name="q" placeholder="어떤 책을 찾고 있나요?" value="${esc(search)}"><button aria-label="검색">${icon('search')}</button></form><a class="mobile-account" href="#/${user()?'profile':'login'}" aria-label="프로필">${icon('person')}</a>${navigation(path)}</div></header>${!['new','edit','login','signup','verify','forgot-password','reset-password'].includes(path)?`<a class="fab" href="#/new" aria-label="책 등록" title="책 등록">${icon('plus')}</a>`:''}<div class="syncbar"><span>한 권의 책이 만드는 새로운 연결</span><button class="quiet sync-refresh" id="refresh" aria-label="목록 새로고침 ↻">${icon('refresh')} 새로고침</button></div><main class="shell">${storageError?`<div class="error">${storageError}</div>`:''}${html}</main><footer><span>▣ 책잇 · 책과 사람을 잇다</span><span>한 권의 책이 만드는 새로운 연결. © 2026 BOOKIT</span></footer>${navigation(path,true)}`;document.body.classList.toggle('form-page',['new','edit','login','signup','verify','forgot-password','reset-password'].includes(path));bind(path);if(!catalogLoading)hydrateMedia($('#app'),data);}
async function digest(value){const bytes=new TextEncoder().encode(value);return [...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(v=>v.toString(16).padStart(2,'0')).join('');}function contactValid(method,v){if(!v.trim())throw Error('연락처를 입력해주세요.');if(method==='이메일'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v))throw Error('올바른 이메일 주소를 입력해주세요.');if(method==='전화번호'&&!/^[+\d ()-]{8,24}$/.test(v))throw Error('전화번호 형식을 확인해주세요.');}async function readImage(file){imagePending++;try{return await prepareImage(file);}finally{imagePending--;}}
function onForm(selector,fn){const el=$(selector);if(el)el.onsubmit=async e=>{e.preventDefault();if(imagePending){toast('사진을 준비하고 있어요. 잠시 후 저장해주세요.');return;}if(['auth','verify','forgot','resetpassword'].includes(el.id)&&!cloud){toast('로그인 연결을 준비하지 못했어요. 페이지를 새로고침해주세요.');return;}if(busy)return;busy=true;const btn=el.querySelector('button.primary');if(btn){btn.disabled=true;btn.dataset.label=btn.textContent;btn.textContent=el.id==='forgot'?'메일 보내는 중…':el.id==='resetpassword'?'비밀번호 변경 중…':'저장 중…';}try{await fn(new FormData(el),el);}catch(err){const box=$('#formerror');if(box)box.textContent=err.message;else toast(err.message);}finally{busy=false;if(btn){btn.disabled=false;btn.textContent=btn.dataset.label;}}};}
function updateBookFieldHelp(){
 if(!$('#bookgenre'))return;
 const genreValue=$('#bookgenre').value,conditionValue=$('#bookcondition').value;
 $('#genreExamples').innerHTML=(genreExamples[genreValue]||[]).map(value=>`<option value="${esc(value)}"></option>`).join('');
 $('#genreDetail').required=genreValue==='기타';$('#conditionDetail').required=conditionValue==='기타';
 $('#genre-detail-help').textContent=genreValue==='기타'?'기타 분야의 세부 장르를 40자 이내로 직접 입력해주세요. (필수)':'예시에서 고르거나 원하는 분류를 40자 이내로 직접 적어주세요. 기본 분야는 기존 검색·추천에 사용돼요.';
 $('#condition-guide').textContent=conditionGuides[conditionValue]+(conditionValue==='기타'?' 상세 설명은 필수예요.':'');
}
function bind(path){bindCloud();
 if($('#bookform')){
  draftHandle=attachBookDraft($('#bookform'),{user:current,id:$('#bookform').dataset.id||'new',cover:()=>imageDraft,applyCover:value=>{imageDraft=value;$('#preview').innerHTML=cover({title:'나의 책',cover:value});},onWarning:toast});
  updateBookFieldHelp();
  $('#bookgenre').onchange=updateBookFieldHelp;$('#bookcondition').onchange=updateBookFieldHelp;
  $('#discard-book-draft').onclick=()=>{if(draftHandle.dirty()&&!confirm('임시 저장한 작성 내용을 비우고 처음부터 작성할까요?'))return;draftHandle.discard();render();};
  $('#clear-condition-detail').onclick=()=>{$('#conditionDetail').value='';draftHandle.save();$('#conditionDetail').focus();};
 }
 document.querySelectorAll('.brand,.top-nav a[href="#/"],.bottom-nav a[href="#/"]').forEach(link=>link.onclick=e=>{if(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;if(draftHandle&&!draftHandle.save()){e.preventDefault();return;}search='';genre='전체';condition='';listPages.home=1;if(location.hash==='#/'||!location.hash){e.preventDefault();render();window.scrollTo(0,0);}});
 document.querySelectorAll('[data-listing]').forEach(el=>el.onclick=async()=>{if(busy)return;if(el.dataset.listing==='archived'&&data.requests.some(r=>r.status==='대기 중'&&[r.target,r.offered].includes(el.dataset.book))&&!confirm('등록을 종료하면 대기 중인 교환 신청도 함께 마감됩니다. 종료할까요?'))return;busy=true;try{await mutate(()=>setListingState(data,el.dataset.book,current,el.dataset.listing));render();toast(el.dataset.listing==='archived'?'등록을 종료했어요. 기록은 유지됩니다.':'다시 등록했어요.');}catch(error){toast(error.message);}finally{busy=false;}});
document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>{const key=path==='recommend'?'recommend':path==='search'?'search':'home';const next=Number(el.dataset.page);if(!Number.isInteger(next)||next<1)return;listPages[key]=next;render();const heading=$('#book-results-heading');heading?.focus({preventScroll:true});heading?.scrollIntoView({block:'start'});});
onForm('#search',f=>{search=f.get('q').trim();genre='전체';condition='';listPages.search=1;if(location.hash==='#/search')render();else go('/search');});document.querySelectorAll('[data-genre]').forEach(el=>el.onclick=()=>{genre=el.dataset.genre;listPages[path==='search'?'search':'home']=1;render();});if($('#condition'))$('#condition').onchange=e=>{condition=e.target.value;listPages[path==='search'?'search':'home']=1;render();};onForm('#auth',async f=>{const email=f.get('email').trim().toLowerCase(),pw=f.get('password');if(path==='signup'){const name=f.get('nickname').trim();if(!name)throw Error('닉네임을 입력해주세요.');const result=await cloud.signup(email,pw,name);if(!result){toast('가입 메일을 확인해주세요. 코드 입력 화면으로 이동합니다.');go('/verify');return;}data=result;}else data=await cloud.login(email,pw);current=cloud.currentId();go('/profile');toast('로그인되었어요.');});if($('#logout'))$('#logout').onclick=async()=>{try{const previous=current;data=await cloud.logout();clearUserDrafts(previous);current=null;storageError=data.loadWarning||'';go('/');}catch(e){toast(e.message);}};if($('#image'))$('#image').onchange=async e=>{const task=++imageTask;try{const compressed=await readImage(e.target.files[0]);if(task!==imageTask)return;imageDraft=compressed;draftHandle?.save();$('#preview').innerHTML=cover({title:'내 책',cover:imageDraft});$('#formerror').textContent='';}catch(err){if(task!==imageTask)return;e.target.value='';if($('#formerror'))$('#formerror').textContent=err.message;}};if($('#removeimage'))$('#removeimage').onclick=()=>{imageTask++;imageDraft='light';$('#image').value='';$('#preview').innerHTML=cover({title:'나의 책',cover:imageDraft});draftHandle?.save();};onForm('#bookform',async(f,el)=>{if(!f.get('title').trim())throw Error('책 제목을 입력해주세요.');contactValid(f.get('method'),f.get('contact'));const id=el.dataset.id,b=id?book(id):null;if(b&&(b.owner!==current||b.status!=='available'))throw Error('이 책은 수정할 수 없어요.');const fields={...Object.fromEntries(f),...validateBookDetails(Object.fromEntries(f))};for(const k of Object.keys(fields))fields[k]=fields[k].trim();await mutate(()=>{if(b)Object.assign(b,fields,{cover:imageDraft});else data.books.unshift({...fields,id:uid(),owner:current,created:Date.now(),cover:imageDraft,status:'available'});});draftHandle?.finish();go('/profile');toast(data.syncWarning||'책을 저장했어요.');});let avatarDraft; if($('#avatarfile'))$('#avatarfile').onchange=async e=>{try{avatarDraft=await readImage(e.target.files[0]);toast('프로필 저장을 누르면 사진이 적용돼요.');}catch(err){$('#formerror').textContent=err.message;}};onForm('#profileform',async f=>{if(!f.get('nickname').trim())throw Error('닉네임을 입력해주세요.');contactValid(f.get('method'),f.get('contact'));if(!avatarDraft&&user().avatar===undefined)user().avatar=await loadMedia('profile',current);await mutate(()=>Object.assign(user(),{nickname:f.get('nickname').trim(),bio:f.get('bio').trim(),contact:f.get('contact').trim(),method:f.get('method'),interests:f.getAll('interests'),keywords:f.get('keywords').trim(),...(avatarDraft?{avatar:avatarDraft}:{})}));render();toast('프로필을 저장했어요.');});onForm('#proposal',async(f,el)=>{await mutate(()=>propose(data,current,el.dataset.target,f.get('offered'),f.get('message').trim()));go('/sent');toast('교환 신청을 보냈어요.');});document.querySelectorAll('[data-delete]').forEach(el=>el.onclick=async()=>{try{const b=book(el.dataset.delete);if(b.owner!==current||b.status!=='available'||data.requests.some(r=>[r.target,r.offered].includes(b.id)))throw Error('교환 기록이 있는 책은 등록 종료를 이용해주세요.');if(!confirm('이 책을 삭제할까요?'))return;await mutate(()=>data.books=data.books.filter(x=>x.id!==b.id));render();toast('책을 삭제했어요.');}catch(e){toast(e.message);}});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=async()=>{if(busy)return;busy=true;el.disabled=true;try{await mutate(()=>transition(data,el.dataset.r,current,el.dataset.action));render();toast('교환 상태를 업데이트했어요.');}catch(e){toast(e.message);}finally{busy=false;if(el.isConnected)el.disabled=false;}});onForm('#notes',async(f,el)=>{const r=data.requests.find(r=>r.id===el.dataset.r);if(r.status!=='수락됨'||![r.from,r.to].includes(current))throw Error('메모를 수정할 수 없어요.');await mutate(()=>r.notes[current]=f.get('note').trim());render();toast('교환 메모를 저장했어요.');});}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
async function refresh(){if(initialLoading){toast('아직 연결 중이에요. 잠시만 기다려주세요.');return;}const api=await deadline(cloudReady);const result=await deadline(api.resume());clearMedia();data=result;current=api.currentId();catalogLoading=false;catalogFailed=false;storageError='';render();}
function legacyImport(){const bs=cloud.legacyBooks().filter(b=>!data.books.some(x=>x.id==='import-'+current+'-'+b.id));return bs.length?`<form id="importbooks" class="notice"><b>이 브라우저에 예전에 등록한 책이 있어요.</b><p>선택한 책을 현재 계정의 공용 책장으로 복사합니다. 원본은 유지됩니다. 연락처는 현재 프로필 연락처를 사용합니다.</p>${bs.map(b=>`<label style="display:block"><input type="checkbox" name="legacy" value="${esc(b.id)}"> ${esc(b.title)}</label>`).join('')}<button class="secondary">선택한 책 가져오기</button></form>`:'';}
function forgotPassword(){return `<form class="form panel" id="forgot"><h1>비밀번호 찾기</h1><p>가입한 이메일로 비밀번호 재설정 링크를 보내드려요.</p><label for="recovery-email">가입 이메일</label><input id="recovery-email" name="email" type="email" autocomplete="email" required><div class="error" id="formerror"></div><p id="recovery-status" role="status"></p><button class="primary">재설정 메일 보내기</button><p><a href="#/login">로그인으로 돌아가기</a></p></form>`;}
function resetPasswordPage(){if(!cloud?.canResetPassword?.())return `<div class="form panel"><h1>재설정 링크를 확인해주세요</h1><p>링크가 만료되었거나 이 탭에 유효한 재설정 세션이 없어요. 메일의 최신 링크로 접속하거나 메일을 다시 요청해주세요.</p><a class="btn" href="#/forgot-password">재설정 메일 다시 요청</a></div>`;return `<form class="form panel" id="resetpassword"><h1>새 비밀번호 설정</h1><label for="newpassword">새 비밀번호</label><input id="newpassword" name="password" type="password" autocomplete="new-password" minlength="8" maxlength="128" required><label for="confirm-password">새 비밀번호 확인</label><input id="confirm-password" name="confirmation" type="password" autocomplete="new-password" minlength="8" maxlength="128" required><p class="hint">8자 이상 입력해주세요. 비밀번호는 임시 저장하지 않아요.</p><div class="error" id="formerror"></div><button class="primary">비밀번호 변경</button><p><a href="#/forgot-password">재설정 메일 다시 요청</a></p></form>`;}
window.addEventListener('bookit:recovery',()=>{if(!initialLoading)queueMicrotask(()=>go('/reset-password'));});
window.addEventListener('beforeunload',event=>{if((draftHandle&&!draftHandle.save())||imagePending){event.preventDefault();event.returnValue='';}});
function verify(){return '<form class="form panel" id="verify"><h1>이메일 확인</h1><p class="hint">가입 메일에 담긴 확인 코드를 입력해주세요. 메일이 없으면 스팸함도 확인해주세요.</p><label>가입 이메일</label><input name="email" type="email" required><label>확인 코드</label><input name="token" required inputmode="numeric" maxlength="20"><div class="error" id="formerror"></div><button class="primary">확인하고 로그인</button></form>';}
function bindCloud(){onForm('#forgot',async f=>{await cloud.requestPasswordReset(f.get('email').trim().toLowerCase());$('#recovery-status').textContent='가입된 이메일이라면 재설정 링크를 보냈어요. 메일함과 스팸함을 확인해주세요. 다시 보내기는 1분 후 가능해요.';$('#formerror').textContent='';});onForm('#resetpassword',async f=>{const previous=current;data=await cloud.resetPassword(f.get('password'),f.get('confirmation'));clearUserDrafts(previous);current=null;const url=new URL(location.href);url.searchParams.delete('recover');url.hash='/login';history.replaceState(null,'',url.pathname+url.search+url.hash);render();toast('비밀번호가 변경됐어요. 새 비밀번호로 로그인해주세요.');});if($('#refresh'))$('#refresh').onclick=async()=>{try{await refresh();toast('최신 목록을 불러왔어요.');}catch(e){toast('목록을 불러오지 못했어요. 잠시 후 다시 시도해주세요.');}};onForm('#importbooks',async f=>{const selected=f.getAll('legacy');if(!selected.length)throw Error('가져올 책을 선택해주세요.');data=await cloud.importLegacy(selected,data);render();toast('선택한 책을 공용 DB로 가져왔어요.');});onForm('#verify',async f=>{data=await cloud.verify(f.get('email').trim(),f.get('token').trim());current=cloud.currentId();go('/profile');toast('이메일 확인이 완료되었어요.');});}
render();
let catalogueAvailable=false;
startLoading({
  catalog:loadCatalog,
  account:async catalogTask=>(await cloudReady).resume(catalogTask),
  onCatalog:catalog=>{data=catalog;catalogueAvailable=true;catalogLoading=false;render();},
  onAccount:result=>{data=result;current=cloud.currentId();initialLoading=false;catalogLoading=false;storageError='';if(cloud.canResetPassword?.()||recoveryEntry)go('/reset-password');render();},
  onError:(stage)=>{
    if(stage==='catalog'){catalogLoading=false;catalogFailed=true;storageError='책 목록 연결이 지연되고 있어요. 목록 새로고침으로 다시 시도해주세요.';}
    else {initialLoading=false;storageError=catalogueAvailable?'책 목록은 볼 수 있어요. 로그인 정보 연결이 지연되어 목록 새로고침이 필요해요.':'연결이 지연되고 있어요. 목록 새로고침으로 다시 시도해주세요.';}
    render();
  },
});
